/* global __PUBLIC_ASSETS__ */
/* Generated by build-pwa.mjs. Never add runtime/API response caching here. */
const CACHE = 'llll-public-__CACHE_ID__'
const ASSETS = __PUBLIC_ASSETS__
const PUBLIC = new Set(ASSETS)
self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE)
    // A failed/partial install must not replace the working version.
    // A few requests at a time: one by one, hundreds of assets take long enough for the
    // next deployment to replace this worker before anyone can activate it.
    const queue = [...ASSETS]
    async function next() {
      for (let path = queue.shift(); path; path = queue.shift()) {
        const response = await fetch(new Request(path, { cache: 'reload', credentials: 'omit' }))
        if (!response.ok || response.redirected) throw new Error('Public asset unavailable: ' + path)
        // A shell without the Worker's policy would serve every page unprotected.
        if (path === '/app-shell' && !response.headers.get('Content-Security-Policy')?.includes('frame-ancestors')) throw new Error('App shell is missing its Content-Security-Policy')
        await cache.put(path, response)
      }
    }
    try { await Promise.all(Array.from({ length: 6 }, next)) }
    catch (error) { queue.length = 0; await caches.delete(CACHE); throw error }
  })())
})
// Keep the preceding cache for tabs that still run the preceding client.
// Each subsequent activation bounds retention to at most two generations.
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = (await caches.keys()).filter(key => key.startsWith('llll-public-') && key !== CACHE)
    await Promise.all(keys.slice(0, -1).map(key => caches.delete(key)))
    await self.clients.claim()
  })())
})
self.addEventListener('message', event => {
  // Request activation independently of this message's lifetime.
  if (event.data?.type === 'ACTIVATE_UPDATE') void self.skipWaiting()
})
self.addEventListener('fetch', event => {
  const request = event.request, url = new URL(request.url)
  // No auth, APIs, signed downloads, cross-origin data, queries or mutations.
  if (request.method !== 'GET' || url.origin !== self.location.origin || (url.pathname.startsWith('/api/') || url.pathname.startsWith('/s/') || url.pathname.startsWith('/.well-known/')) || request.headers.has('Authorization')) return
  if (request.mode === 'navigate') {
    // The MCP consent page forbids framing entirely; only the Worker sends that policy.
    if (url.pathname.startsWith('/mcp/')) return
    // Serve one consistent client generation, including offline deep links. The shell was
    // fetched from the Worker, so it carries this Server's CSP and frame-ancestors.
    event.respondWith(caches.open(CACHE).then(cache => cache.match('/app-shell')).then(response => response || fetch(request)))
    return
  }
  if (url.search || (!PUBLIC.has(url.pathname) && !url.pathname.startsWith('/_nuxt/'))) return
  event.respondWith((async () => {
    const current = await caches.open(CACHE)
    const response = await current.match(url.pathname)
    if (response) return response
    // Retained immutable assets can still be requested by an older open tab.
    for (const key of await caches.keys()) {
      if (key.startsWith('llll-public-')) {
        const previous = await (await caches.open(key)).match(url.pathname)
        if (previous) return previous
      }
    }
    return fetch(request)
  })())
})
